import { defineComponent, ref, h } from '@vue/composition-api';
import { AsyncTemplateConfig } from '@/config/config';
import CommonComponent from '@/config/common';
import styles from './index.module.scss';
import Word from '@/main/components/word';
import { useGeneratePdfDataInject } from '@/main/context';
import { PeriodSubjectCategoryEnum } from '@/config/types';

/** 问题探究组件 */
export default defineComponent({
  name: 'WordsQuestion',
  props: {
    /** 该组件所有值 */
    data: {
      type: Object,
      default: function _default() {
        return {};
      }
    },
    /** 用于指学框的唯一标识 */
    code: {
      type: String
    }
  },
  setup: function setup(props) {
    // 组件外边框
    var customMargin = ref();
    var _useGeneratePdfDataIn = useGeneratePdfDataInject(),
      periodSubjectCategory = _useGeneratePdfDataIn.periodSubjectCategory;
    switch (periodSubjectCategory.value) {
      case PeriodSubjectCategoryEnum.XIAOXUE_CHINESE_HJYX:
        customMargin.value = AsyncTemplateConfig.link_issueInquiry.chineseHJYXConfig.margin.generateString();
        break;
      default:
        customMargin.value = AsyncTemplateConfig.link_issueInquiry.config.margin.generateString();
        break;
    }
    return function () {
      return h(CommonComponent, {
        "attrs": {
          "customClass": [styles.linkIssueInquiry],
          "margin": customMargin.value
        },
        "style": props.data.customStyle
      }, [h(Word, {
        "style": AsyncTemplateConfig.link_issueInquiry.config.font,
        "attrs": {
          "content": props.data.data.content
        }
      })]);
    };
  }
});